// ============================================================
// sw2007_full.mod —— Smets-Wouters (2007) 中尺度 DSGE 教学完整版
// 六大摩擦(习惯/投资调整成本/资本利用/Calvo价格/Calvo工资/指数化)
// 七冲击(技术/投资专用/政府支出/货币/价格加成/工资加成/风险溢价)
// 求解：order=2 + pruning
// 运行：dynare sw2007_full.mod
// 所有变量为偏离稳态的对数/百分点
// ============================================================

// ---------- Step 1: 内生变量声明 ----------
var
  y          // 产出
  c          // 消费
  i          // 投资
  n          // 劳动(工时)
  pi         // 通胀
  r          // 名义利率(联邦基金)
  rn         // 风险溢价/偏好冲击过程
  rk         // 资本实际租金
  w          // 实际工资
  mc         // 实际边际成本
  q          // 托宾Q
  k          // 资本存量(滞后状态)
  kbar       // 有效资本 = u + k(-1)
  u          // 资本利用率
  pi_w       // 工资通胀
  mrs        // 劳动边际替代率
  g          // 政府支出
  a          // 技术过程
  b          // 偏好/风险溢价过程
  p_shock    // 价格加成过程
  w_shock    // 工资加成过程
  i_shock    // 投资专用技术过程
;

// ---------- Step 2: 外生冲击声明(7个) ----------
varexo
  eps_a      // 技术冲击
  eps_i      // 投资专用技术冲击
  eps_g      // 政府支出冲击
  eps_m      // 货币政策冲击
  eps_p      // 价格加成冲击
  eps_w      // 工资加成冲击
  eps_b      // 风险溢价/偏好冲击
;

// ---------- Step 3: 参数声明与校准 ----------
parameters beta sigma h phi varphi alpha delta ...
    theta_p theta_w gamma_p gamma_w psi invadj ...
    phi_pi phi_y rho_i ...
    rho_a rho_i2 rho_g rho_m rho_p rho_w rho_b;

beta=0.99;          // 季度贴现因子(年化4%)
sigma=1.5;          // 风险厌恶系数
h=0.7;              // 习惯形成参数(SW后验≈0.7)
phi=2.0;            // 劳动Frisch逆弹性
alpha=0.33;         // 资本份额
delta=0.025;        // 季度折旧率(年10%)
theta_p=0.75;       // 价格Calvo不调价概率(平均1年合同)
theta_w=0.75;       // 工资Calvo不调价概率
gamma_p=0.5;        // 价格指数化程度
gamma_w=0.5;        // 工资指数化程度
psi=0.5;            // 资本利用成本曲率
invadj=5.0;         // 投资调整成本曲率 S''
phi_pi=1.5;         // Taylor对通胀反应
phi_y=0.125;        // Taylor对产出反应
rho_i=0.75;         // 利率平滑
// 7个AR(1)持续性
rho_a=0.95; rho_i2=0.71; rho_g=0.97; rho_m=0.15;
rho_p=0.90; rho_w=0.90; rho_b=0.22;

// ---------- Step 4: 模型方程 ----------
model;
// (1) 习惯形成下的消费欧拉(含偏好冲击 b)
c = h/(1+h)*c(-1) + 1/(1+h)*c(+1) ...
    - (1-h)/(sigma*(1+h))*( r - pi(+1) ) + b;

// (2) 投资欧拉(含调整成本与投资专用冲击 i_shock)
i = 1/(1+beta)*( i(-1) + beta*i(+1) ) ...
    + 1/((1+beta)*invadj)*q + i_shock;

// (3) 托宾Q资产定价方程
q = -( r - pi(+1) ) + beta*(1-delta)*q(+1) ...
    + (1-beta*(1-delta))*rk(+1);

// (4) 资本利用: rk = psi * u
rk = psi*u;

// (5) 有效资本 = 利用率 + 滞后资本
kbar = u + k(-1);

// (6) 资本积累
k = (1-delta)*k(-1) + delta*i;

// (7) 生产函数(忽略固定成本phi)
y = a + alpha*kbar + (1-alpha)*n;

// (8) 边际成本
mc = (1-alpha)*w + alpha*rk - a;

// (9) 资源约束(简化: y = c + i + g)
y = c + i + g;

// (10) 价格NKPC(含指数化gamma_p与价格加成冲击)
pi = beta/(1+beta*gamma_p)*pi(+1) ...
    + gamma_p/(1+beta*gamma_p)*pi(-1) ...
    + ((1-theta_p)*(1-beta*theta_p))/(theta_p*(1+beta*gamma_p))*mc ...
    + p_shock;

// (11) 劳动边际替代率(含习惯 h)
mrs = phi*n + sigma/(1-h)*( c - h*c(-1) );

// (12) 工资Phillips曲线(含指数化gamma_w)
pi_w = beta/(1+beta)*pi_w(+1) + 1/(1+beta)*pi_w(-1) ...
     + gamma_w/(1+beta)*pi(-1) ...
     - (1+beta*gamma_w)/(1+beta)*pi + beta/(1+beta)*pi(+1) ...
     + ((1-theta_w)*(1-beta*theta_w))/(theta_w*(1+beta))*( mrs - w ) ...
     + w_shock;

// (13) 实际工资累积关系: w = w(-1) + pi_w - pi
w = w(-1) + pi_w - pi;

// (14) Taylor规则(含利率平滑与货币冲击 eps_m)
r = rho_i*r(-1) ...
    + (1-rho_i)*( phi_pi*pi + phi_y*y ) + eps_m;

// (15-21) 7个外生冲击的AR(1)过程
a       = rho_a*a(-1)       + eps_a;     // 技术
i_shock= rho_i2*i_shock(-1) + eps_i;    // 投资专用
g       = rho_g*g(-1)       + eps_g;    // 政府支出
p_shock = rho_p*p_shock(-1) + eps_p;    // 价格加成
w_shock = rho_w*w_shock(-1) + eps_w;    // 工资加成
b       = rho_b*b(-1)       + eps_b;    // 风险溢价/偏好
// eps_m 已直接进Taylor规则
end;

// ---------- Step 5: 稳态求解 ----------
// 对数线性化模型: 所有变量稳态=0
// 若写非线性原始模型, 先 initval; 给猜测:
//   initval;  y=1; c=0.59; i=0.23; k=9.3; n=1/3; pi=0; r=0.01; end;
//   steady; resid;   // resid; 检查稳态残差
steady;

// ---------- Step 6: Blanchard-Kahn 诊断 ----------
check;

// ---------- Step 7: 冲击方差 ----------
shocks;
var eps_a = 0.0045^2;   // 技术
var eps_i = 0.10^2;     // 投资专用
var eps_g = 0.02^2;     // 政府支出
var eps_m = 0.0025^2;   // 货币
var eps_p = 0.01^2;     // 价格加成
var eps_w = 0.05^2;     // 工资加成
var eps_b = 0.10^2;     // 风险溢价
end;

// ---------- Step 8: 二阶求解 + pruning + IRF ----------
// order=2: 二阶扰动,含风险修正
// pruning: 抑制高阶矩累积发散(中尺度多冲击必开)
// irf=40: 画40期脉冲
stoch_simul(order=2, irf=40, pruning, nograph) ...
  y c i n pi r w rk q kbar u;

// ============================================================
// ===== Step 9 (估计用): 贝叶斯估计块 =====
// 跑估计时把上面 stoch_simul 注释掉, 打开以下块:
// ============================================================
// (a) 数据声明: 7个观测变量(与9.1表一一对应)
// varobs  y_obs c_obs i_obs w_obs n_obs pi_obs r_obs;
// 数据文件 sw_us_data.m 或 .xlsx 需在运行目录, 列顺序同上,
// 已按 9.1 处理: 对数差分×100 / ×400 / 利率÷4 / 工时去趋势.

// (b) 先验(对应9.3表): 分布(mean,std)
// estimated_params;
//   h,           beta_pdf,   0.70, 0.10;     // 习惯
//   sigma,       normal_pdf, 1.50, 0.37;     // 效用曲率
//   phi,         normal_pdf, 2.00, 0.75;    // Frisch逆
//   inv

% ---- 在 .mod 文件结尾 ----
% order=1: 一阶(=对数线性化), 快, 无风险效应
% order=2: 二阶, 捕捉风险溢价/预防性储蓄, 默认 pruning
% order=3: 三阶, 捕捉时变波动率(不确定性冲击)
stoch_simul(order=1, irf=40, nograph) y pi i k;
stoch_simul(order=2, irf=40, nograph) y pi i k;
stoch_simul(order=3, irf=40, nograph) y pi i k;

% 二阶下查看"风险修正稳态": Dynare 打印的 ys (二阶稳态)
% 与一阶 ys 的差即 g_{\sigma\sigma} 平移量
% moments 选项给出二阶/三阶下的无条件矩
stoch_simul(order=2, periods=10000, drop=100) y pi i k;

